///\n// APURAÇÃO\n//////////////////////////////////////////////////////\n\nmodel ApuracaoDiaria {\n  id                             String         @id @default(cuid()) @map(\"id\")\n  servidorId                     String         @map(\"servidor_id\")\n  data                           DateTime       @map(\"data\")\n  minutosPrevistos               Int            @map(\"minutos_previstos\")\n  minutosTrabalhados             Int            @map(\"minutos_trabalhados\")\n  minutosIntervalo               Int            @map(\"minutos_intervalo\")\n  minutosDebito                  Int            @map(\"minutos_debito\")\n  minutosCredito                 Int            @map(\"minutos_credito\")\n  minutosNaoAutorizados          Int            @map(\"minutos_nao_autorizados\")\n  minutosAcimaLimite             Int            @map(\"minutos_acima_limite\")\n  minutosExcedenteSabado         Int            @map(\"minutos_excedente_sabado\")\n  minutosExcedenteDomingoFeriado Int            @map(\"minutos_excedente_domingo_feriado\")\n  minutosExcedenteNoturno        Int            @map(\"minutos_excedente_noturno\")\n  status                         StatusApuracao @default(OK) @map(\"status\")\n  flags                          String[]       @map(\"flags\")\n\n  servidor Servidor @relation(fields: [servidorId], references: [id], onDelete: Cascade)\n\n  @@unique([servidorId, data], map: \"uk_apuracoes_diarias_servidor_data\")\n  @@map(\"apuracoes_diarias\")\n}\n\nmodel ApuracaoMensal {\n  id                 String         @id @default(cuid()) @map(\"id\")\n  servidorId         String         @map(\"servidor_id\")\n  referenciaMes      String         @map(\"referencia_mes\")\n  minutosPrevistos   Int            @map(\"minutos_previstos\")\n  minutosTrabalhados Int            @map(\"minutos_trabalhados\")\n  minutosDebito      Int            @map(\"minutos_debito\")\n  minutosCredito     Int            @map(\"minutos_credito\")\n  saldoMinutos       Int            @map(\"saldo_m